import type { NextConfig } from 'next';

// Standalone service pages: static HTML in /public, served at clean URLs.
// AI SEO is the master design; the others are generated by scripts/service_pages/build.py.
const servicePages = [
  'ai-seo-services',
  'local-seo-services',
  'gmb-optimization-services',
  'ecommerce-seo-services',
  'backlinks-digital-pr-services',
  'seo-content-writing-services',
];

const nextConfig: NextConfig = {
  async rewrites() {
    return [
      ...servicePages.map(slug => ({ source: `/${slug}`, destination: `/${slug}.html` })),
      // Client audit reports: public/share/<name>.html is served at /share/<name>.
      { source: '/share/:report', destination: '/share/:report.html' },
    ];
  },
  async redirects() {
    // Keep one canonical URL for each page.
    return servicePages.map(slug => ({ source: `/${slug}.html`, destination: `/${slug}`, permanent: true }));
  },
};

export default nextConfig;
